import { useContext } from "react";
import { AppContext } from "../../context/AppContext";

export default function Reports() {
  const { adminOrders } = useContext(AppContext);

  const completed = adminOrders.filter(o => o.status === "Completed");
  const revenue = completed.reduce((sum, o) => sum + o.amount, 0);

  const itemCount = {};
  adminOrders.forEach(o =>
    o.items.forEach(i => {
      itemCount[i.name] = (itemCount[i.name] || 0) + i.qty;
    })
  );

  const topItem = Object.entries(itemCount).sort((a, b) => b[1] - a[1])[0]?.[0] || "–";

  return (
    <div className="stat-cards">
      <div className="stat-card">
        <div className="stat-card-title">Revenue</div>
        <div className="stat-card-value">₹{revenue}</div>
      </div>
      <div className="stat-card">
        <div className="stat-card-title">Orders</div>
        <div className="stat-card-value">{adminOrders.length}</div>
      </div>
      <div className="stat-card">
        <div className="stat-card-title">Top Item</div>
        <div className="stat-card-value">{topItem}</div>
      </div>
    </div>
  );
}
